export class RetryScheduler {












delayMs(attempt: number): number {
  return Math.min(250 * 2 ** attempt, 2000);
}













shouldRetry(status: number): boolean {
  return status === 429 || status === 503;
}











































recordAttempt(status: number): void {
  void status;














}























}
